import{_ as l,H as e,f as i,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"第一法典","description":"","frontmatter":{"title":"第一法典","outline":"deep"},"headers":[],"relativePath":"rules1.md","filePath":"rules1.md"}'),o={name:"rules1.md"};function h(t,a,n,d,s,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第一法典" tabindex="-1">第一法典 <a class="header-anchor" href="#第一法典" aria-label="Permalink to &quot;第一法典&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PIGLIN KINGDOM 大法典 第一法典（第1条～第50条）</p></div><h1 id="第一編-王権" tabindex="-1">第一編 王権 <a class="header-anchor" href="#第一編-王権" aria-label="Permalink to &quot;第一編 王権&quot;">​</a></h1><h2 id="第一章-国王" tabindex="-1">第一章 国王 <a class="header-anchor" href="#第一章-国王" aria-label="Permalink to &quot;第一章 国王&quot;">​</a></h2><h3 id="第1条-国王の地位" tabindex="-1">第1条 国王の地位 <a class="header-anchor" href="#第1条-国王の地位" aria-label="Permalink to &quot;第1条 国王の地位&quot;">​</a></h3><ol><li>国王は PIGLIN KINGDOM の最高統治者である。</li><li>国王は軍事、財政、外交及び司法を統括する。</li><li>国王の正式称号は「黄金王」とする。</li></ol><h3 id="第2条-王位継承" tabindex="-1">第2条 王位継承 <a class="header-anchor" href="#第2条-王位継承" aria-label="Permalink to &quot;第2条 王位継承&quot;">​</a></h3><ol><li>王位は王家に属する。</li><li>国王は後継者を指名できる。</li><li>指名がない場合は最年長の子が王位を継承する。</li></ol><h3 id="第3条-勅令" tabindex="-1">第3条 勅令 <a class="header-anchor" href="#第3条-勅令" aria-label="Permalink to &quot;第3条 勅令&quot;">​</a></h3><ol><li>勅令は通常の法律に優先する。</li><li>緊急勅令は即時に効力を有する。</li><li>国王は大法典を改正できる。</li></ol><hr><h2 id="第二章-王家" tabindex="-1">第二章 王家 <a class="header-anchor" href="#第二章-王家" aria-label="Permalink to &quot;第二章 王家&quot;">​</a></h2><h3 id="第4条-王家" tabindex="-1">第4条 王家 <a class="header-anchor" href="#第4条-王家" aria-label="Permalink to &quot;第4条 王家&quot;">​</a></h3><ol><li>王家の構成員は王国に奉仕する。</li><li>王家の構成員は黄金の紋章を身に着ける。</li></ol><h3 id="第5条-摂政" tabindex="-1">第5条 摂政 <a class="header-anchor" href="#第5条-摂政" aria-label="Permalink to &quot;第5条 摂政&quot;">​</a></h3><ol><li>国王不在時には摂政が統治を代行する。</li><li>摂政は王立評議会の承認を受けなければならない。</li></ol><hr><h1 id="第二編-国民" tabindex="-1">第二編 国民 <a class="header-anchor" href="#第二編-国民" aria-label="Permalink to &quot;第二編 国民&quot;">​</a></h1><h2 id="第一章-国籍" tabindex="-1">第一章 国籍 <a class="header-anchor" href="#第一章-国籍" aria-label="Permalink to &quot;第一章 国籍&quot;">​</a></h2><h3 id="第6条-国籍" tabindex="-1">第6条 国籍 <a class="header-anchor" href="#第6条-国籍" aria-label="Permalink to &quot;第6条 国籍&quot;">​</a></h3><ol><li>王国内で生まれた者は国民となる。</li><li>国王の許可によって国籍を取得できる。</li></ol><h3 id="第7条-忠誠" tabindex="-1">第7条 忠誠 <a class="header-anchor" href="#第7条-忠誠" aria-label="Permalink to &quot;第7条 忠誠&quot;">​</a></h3><ol><li>国民は王国への忠誠を誓う。</li><li>成年者は忠誠の儀式に参加する。</li></ol><h3 id="第8条-財産権" tabindex="-1">第8条 財産権 <a class="header-anchor" href="#第8条-財産権" aria-label="Permalink to &quot;第8条 財産権&quot;">​</a></h3><ol><li>私有財産を認める。</li><li>王室は補償を伴って財産を徴用できる。</li></ol><h3 id="第9条-信仰" tabindex="-1">第9条 信仰 <a class="header-anchor" href="#第9条-信仰" aria-label="Permalink to &quot;第9条 信仰&quot;">​</a></h3><ol><li>黄金祭を保護する。</li><li>その他の信仰も認める。</li></ol><hr><h1 id="第三編-行政" tabindex="-1">第三編 行政 <a class="header-anchor" href="#第三編-行政" aria-label="Permalink to &quot;第三編 行政&quot;">​</a></h1><h2 id="第一章-地方行政" tabindex="-1">第一章 地方行政 <a class="header-anchor" href="#第一章-地方行政" aria-label="Permalink to &quot;第一章 地方行政&quot;">​</a></h2><h3 id="第10条-州" tabindex="-1">第10条 州 <a class="header-anchor" href="#第10条-州" aria-label="Permalink to &quot;第10条 州&quot;">​</a></h3><ol><li>王国は複数の州によって構成される。</li><li>各州には総督を置く。</li></ol><h3 id="第11条-総督" tabindex="-1">第11条 総督 <a class="header-anchor" href="#第11条-総督" aria-label="Permalink to &quot;第11条 総督&quot;">​</a></h3><ol><li>総督は国王が任命する。</li><li>任期は10年とする。</li></ol><h3 id="第12条-官吏" tabindex="-1">第12条 官吏 <a class="header-anchor" href="#第12条-官吏" aria-label="Permalink to &quot;第12条 官吏&quot;">​</a></h3><ol><li>官吏は王室への忠誠を負う。</li><li>汚職を禁ずる。</li></ol><h3 id="第13条-公文書" tabindex="-1">第13条 公文書 <a class="header-anchor" href="#第13条-公文書" aria-label="Permalink to &quot;第13条 公文書&quot;">​</a></h3><ol><li>公文書には王国暦を用いる。</li><li>偽造を禁ずる。</li></ol><hr><h1 id="第四編-財政" tabindex="-1">第四編 財政 <a class="header-anchor" href="#第四編-財政" aria-label="Permalink to &quot;第四編 財政&quot;">​</a></h1><h2 id="第一章-税制" tabindex="-1">第一章 税制 <a class="header-anchor" href="#第一章-税制" aria-label="Permalink to &quot;第一章 税制&quot;">​</a></h2><h3 id="第14条-通貨" tabindex="-1">第14条 通貨 <a class="header-anchor" href="#第14条-通貨" aria-label="Permalink to &quot;第14条 通貨&quot;">​</a></h3><ol><li>王国の公式通貨は金インゴットである。</li><li>王立銀行が通貨を発行する。</li></ol><h3 id="第15条-所得税" tabindex="-1">第15条 所得税 <a class="header-anchor" href="#第15条-所得税" aria-label="Permalink to &quot;第15条 所得税&quot;">​</a></h3><ol><li>国民は所得の10パーセントを納税する。</li></ol><h3 id="第16条-採掘税" tabindex="-1">第16条 採掘税 <a class="header-anchor" href="#第16条-採掘税" aria-label="Permalink to &quot;第16条 採掘税&quot;">​</a></h3><ol><li>採掘資源の20パーセントを王室に納める。</li></ol><h3 id="第17条-商業税" tabindex="-1">第17条 商業税 <a class="header-anchor" href="#第17条-商業税" aria-label="Permalink to &quot;第17条 商業税&quot;">​</a></h3><ol><li>商人は売上の5パーセントを納税する。</li></ol><hr><h1 id="第五編-軍法" tabindex="-1">第五編 軍法 <a class="header-anchor" href="#第五編-軍法" aria-label="Permalink to &quot;第五編 軍法&quot;">​</a></h1><h2 id="第一章-軍隊" tabindex="-1">第一章 軍隊 <a class="header-anchor" href="#第一章-軍隊" aria-label="Permalink to &quot;第一章 軍隊&quot;">​</a></h2><h3 id="第18条-王立軍" tabindex="-1">第18条 王立軍 <a class="header-anchor" href="#第18条-王立軍" aria-label="Permalink to &quot;第18条 王立軍&quot;">​</a></h3><ol><li>王立軍は王国を防衛する。</li><li>国王は最高司令官である。</li></ol><h3 id="第19条-黄金親衛隊" tabindex="-1">第19条 黄金親衛隊 <a class="header-anchor" href="#第19条-黄金親衛隊" aria-label="Permalink to &quot;第19条 黄金親衛隊&quot;">​</a></h3><ol><li>黄金親衛隊は王直属の精鋭部隊である。</li><li>親衛隊は国王への忠誠を誓う。</li></ol><h3 id="第20条-戒厳令" tabindex="-1">第20条 戒厳令 <a class="header-anchor" href="#第20条-戒厳令" aria-label="Permalink to &quot;第20条 戒厳令&quot;">​</a></h3><ol><li>戦時には戒厳令を布告できる。</li><li>軍は治安維持を行う。</li></ol><hr><h1 id="第六編-刑法" tabindex="-1">第六編 刑法 <a class="header-anchor" href="#第六編-刑法" aria-label="Permalink to &quot;第六編 刑法&quot;">​</a></h1><h2 id="第一章-犯罪" tabindex="-1">第一章 犯罪 <a class="header-anchor" href="#第一章-犯罪" aria-label="Permalink to &quot;第一章 犯罪&quot;">​</a></h2><h3 id="第21条-窃盗" tabindex="-1">第21条 窃盗 <a class="header-anchor" href="#第21条-窃盗" aria-label="Permalink to &quot;第21条 窃盗&quot;">​</a></h3><ol><li>財産の窃盗を禁ずる。</li><li>違反者には罰金を科す。</li></ol><h3 id="第22条-詐欺" tabindex="-1">第22条 詐欺 <a class="header-anchor" href="#第22条-詐欺" aria-label="Permalink to &quot;第22条 詐欺&quot;">​</a></h3><ol><li>詐欺による財産取得を禁ずる。</li></ol><h3 id="第23条-放火" tabindex="-1">第23条 放火 <a class="header-anchor" href="#第23条-放火" aria-label="Permalink to &quot;第23条 放火&quot;">​</a></h3><ol><li>建造物への放火を禁ずる。</li></ol><h3 id="第24条-偽造通貨" tabindex="-1">第24条 偽造通貨 <a class="header-anchor" href="#第24条-偽造通貨" aria-label="Permalink to &quot;第24条 偽造通貨&quot;">​</a></h3><ol><li>偽造通貨の製造及び流通を禁ずる。</li></ol><h3 id="第25条-密輸" tabindex="-1">第25条 密輸 <a class="header-anchor" href="#第25条-密輸" aria-label="Permalink to &quot;第25条 密輸&quot;">​</a></h3><ol><li>違法な取引を禁ずる。</li></ol><h3 id="第26条-反逆" tabindex="-1">第26条 反逆 <a class="header-anchor" href="#第26条-反逆" aria-label="Permalink to &quot;第26条 反逆&quot;">​</a></h3><ol><li>王権転覆を目的とする行為を禁ずる。</li></ol><h3 id="第27条-敵国との共謀" tabindex="-1">第27条 敵国との共謀 <a class="header-anchor" href="#第27条-敵国との共謀" aria-label="Permalink to &quot;第27条 敵国との共謀&quot;">​</a></h3><ol><li>敵対勢力との協力を禁ずる。</li></ol><hr><h1 id="第七編-商業" tabindex="-1">第七編 商業 <a class="header-anchor" href="#第七編-商業" aria-label="Permalink to &quot;第七編 商業&quot;">​</a></h1><h2 id="第一章-市場" tabindex="-1">第一章 市場 <a class="header-anchor" href="#第一章-市場" aria-label="Permalink to &quot;第一章 市場&quot;">​</a></h2><h3 id="第28条-市場" tabindex="-1">第28条 市場 <a class="header-anchor" href="#第28条-市場" aria-label="Permalink to &quot;第28条 市場&quot;">​</a></h3><ol><li>市場は毎週開催する。</li></ol><h3 id="第29条-商人免許" tabindex="-1">第29条 商人免許 <a class="header-anchor" href="#第29条-商人免許" aria-label="Permalink to &quot;第29条 商人免許&quot;">​</a></h3><ol><li>商人は営業免許を取得しなければならない。</li></ol><h3 id="第30条-物々交換" tabindex="-1">第30条 物々交換 <a class="header-anchor" href="#第30条-物々交換" aria-label="Permalink to &quot;第30条 物々交換&quot;">​</a></h3><ol><li>物々交換を認める。</li></ol><hr><h1 id="第八編-建設" tabindex="-1">第八編 建設 <a class="header-anchor" href="#第八編-建設" aria-label="Permalink to &quot;第八編 建設&quot;">​</a></h1><h2 id="第一章-都市整備" tabindex="-1">第一章 都市整備 <a class="header-anchor" href="#第一章-都市整備" aria-label="Permalink to &quot;第一章 都市整備&quot;">​</a></h2><h3 id="第31条-道路" tabindex="-1">第31条 道路 <a class="header-anchor" href="#第31条-道路" aria-label="Permalink to &quot;第31条 道路&quot;">​</a></h3><ol><li>幹線道路は幅5ブロック以上とする。</li></ol><h3 id="第32条-防火" tabindex="-1">第32条 防火 <a class="header-anchor" href="#第32条-防火" aria-label="Permalink to &quot;第32条 防火&quot;">​</a></h3><ol><li>溶岩の周囲には防護設備を設ける。</li></ol><h3 id="第33条-城壁" tabindex="-1">第33条 城壁 <a class="header-anchor" href="#第33条-城壁" aria-label="Permalink to &quot;第33条 城壁&quot;">​</a></h3><ol><li>城壁の高さは20ブロック以上とする。</li></ol><hr><h1 id="第九編-農業" tabindex="-1">第九編 農業 <a class="header-anchor" href="#第九編-農業" aria-label="Permalink to &quot;第九編 農業&quot;">​</a></h1><h2 id="第一章-農地" tabindex="-1">第一章 農地 <a class="header-anchor" href="#第一章-農地" aria-label="Permalink to &quot;第一章 農地&quot;">​</a></h2><h3 id="第34条-農地" tabindex="-1">第34条 農地 <a class="header-anchor" href="#第34条-農地" aria-label="Permalink to &quot;第34条 農地&quot;">​</a></h3><ol><li>農地を放棄してはならない。</li></ol><h3 id="第35条-家畜" tabindex="-1">第35条 家畜 <a class="header-anchor" href="#第35条-家畜" aria-label="Permalink to &quot;第35条 家畜&quot;">​</a></h3><ol><li>ホグリン及びストライダーの繁殖を保護する。</li></ol><hr><h1 id="第十編-鉱業" tabindex="-1">第十編 鉱業 <a class="header-anchor" href="#第十編-鉱業" aria-label="Permalink to &quot;第十編 鉱業&quot;">​</a></h1><h2 id="第一章-採掘" tabindex="-1">第一章 採掘 <a class="header-anchor" href="#第一章-採掘" aria-label="Permalink to &quot;第一章 採掘&quot;">​</a></h2><h3 id="第36条-鉱山" tabindex="-1">第36条 鉱山 <a class="header-anchor" href="#第36条-鉱山" aria-label="Permalink to &quot;第36条 鉱山&quot;">​</a></h3><ol><li>採掘権は王室に属する。</li></ol><h3 id="第37条-古代の残骸" tabindex="-1">第37条 古代の残骸 <a class="header-anchor" href="#第37条-古代の残骸" aria-label="Permalink to &quot;第37条 古代の残骸&quot;">​</a></h3><ol><li>発見した者は王立財務省へ報告する。</li></ol><hr><h1 id="第十一編-環境" tabindex="-1">第十一編 環境 <a class="header-anchor" href="#第十一編-環境" aria-label="Permalink to &quot;第十一編 環境&quot;">​</a></h1><h2 id="第一章-自然保護" tabindex="-1">第一章 自然保護 <a class="header-anchor" href="#第一章-自然保護" aria-label="Permalink to &quot;第一章 自然保護&quot;">​</a></h2><h3 id="第38条-真紅の森" tabindex="-1">第38条 真紅の森 <a class="header-anchor" href="#第38条-真紅の森" aria-label="Permalink to &quot;第38条 真紅の森&quot;">​</a></h3><ol><li>真紅の森を保護する。</li></ol><h3 id="第39条-溶岩湖" tabindex="-1">第39条 溶岩湖 <a class="header-anchor" href="#第39条-溶岩湖" aria-label="Permalink to &quot;第39条 溶岩湖&quot;">​</a></h3><ol><li>溶岩湖を汚染してはならない。</li></ol><hr><h1 id="第十二編-教育" tabindex="-1">第十二編 教育 <a class="header-anchor" href="#第十二編-教育" aria-label="Permalink to &quot;第十二編 教育&quot;">​</a></h1><h2 id="第一章-学校" tabindex="-1">第一章 学校 <a class="header-anchor" href="#第一章-学校" aria-label="Permalink to &quot;第一章 学校&quot;">​</a></h2><h3 id="第40条-教育" tabindex="-1">第40条 教育 <a class="header-anchor" href="#第40条-教育" aria-label="Permalink to &quot;第40条 教育&quot;">​</a></h3><ol><li>全ての子どもは教育を受ける権利を有する。</li></ol><h3 id="第41条-必修科目" tabindex="-1">第41条 必修科目 <a class="header-anchor" href="#第41条-必修科目" aria-label="Permalink to &quot;第41条 必修科目&quot;">​</a></h3><ol><li>歴史</li><li>採掘学</li><li>戦術学</li><li>交易学</li></ol><hr><h1 id="第十三編-科学技術" tabindex="-1">第十三編 科学技術 <a class="header-anchor" href="#第十三編-科学技術" aria-label="Permalink to &quot;第十三編 科学技術&quot;">​</a></h1><h2 id="第一章-発明" tabindex="-1">第一章 発明 <a class="header-anchor" href="#第一章-発明" aria-label="Permalink to &quot;第一章 発明&quot;">​</a></h2><h3 id="第42条-発明" tabindex="-1">第42条 発明 <a class="header-anchor" href="#第42条-発明" aria-label="Permalink to &quot;第42条 発明&quot;">​</a></h3><ol><li>発明者は特許を取得できる。</li></ol><h3 id="第43条-レッドストーン機械" tabindex="-1">第43条 レッドストーン機械 <a class="header-anchor" href="#第43条-レッドストーン機械" aria-label="Permalink to &quot;第43条 レッドストーン機械&quot;">​</a></h3><ol><li>大型機械は登録を要する。</li></ol><hr><h1 id="第十四編-外交" tabindex="-1">第十四編 外交 <a class="header-anchor" href="#第十四編-外交" aria-label="Permalink to &quot;第十四編 外交&quot;">​</a></h1><h2 id="第一章-外交" tabindex="-1">第一章 外交 <a class="header-anchor" href="#第一章-外交" aria-label="Permalink to &quot;第一章 外交&quot;">​</a></h2><h3 id="第44条-条約" tabindex="-1">第44条 条約 <a class="header-anchor" href="#第44条-条約" aria-label="Permalink to &quot;第44条 条約&quot;">​</a></h3><ol><li>条約締結権は国王に属する。</li></ol><h3 id="第45条-大使館" tabindex="-1">第45条 大使館 <a class="header-anchor" href="#第45条-大使館" aria-label="Permalink to &quot;第45条 大使館&quot;">​</a></h3><ol><li>外国に大使館を設置できる。</li></ol><hr><h1 id="第十五編-国家行事" tabindex="-1">第十五編 国家行事 <a class="header-anchor" href="#第十五編-国家行事" aria-label="Permalink to &quot;第十五編 国家行事&quot;">​</a></h1><h2 id="第一章-祝祭日" tabindex="-1">第一章 祝祭日 <a class="header-anchor" href="#第一章-祝祭日" aria-label="Permalink to &quot;第一章 祝祭日&quot;">​</a></h2><h3 id="第46条-黄金祭" tabindex="-1">第46条 黄金祭 <a class="header-anchor" href="#第46条-黄金祭" aria-label="Permalink to &quot;第46条 黄金祭&quot;">​</a></h3><ol><li>黄金祭を毎年開催する。</li></ol><h3 id="第47条-建国記念日" tabindex="-1">第47条 建国記念日 <a class="header-anchor" href="#第47条-建国記念日" aria-label="Permalink to &quot;第47条 建国記念日&quot;">​</a></h3><ol><li>建国記念日は国民の祝日とする。</li></ol><hr><h1 id="第十六編-鉄道法" tabindex="-1">第十六編 鉄道法 <a class="header-anchor" href="#第十六編-鉄道法" aria-label="Permalink to &quot;第十六編 鉄道法&quot;">​</a></h1><h2 id="第一章-鉄道" tabindex="-1">第一章 鉄道 <a class="header-anchor" href="#第一章-鉄道" aria-label="Permalink to &quot;第一章 鉄道&quot;">​</a></h2><h3 id="第48条-線路" tabindex="-1">第48条 線路 <a class="header-anchor" href="#第48条-線路" aria-label="Permalink to &quot;第48条 線路&quot;">​</a></h3><ol><li>無断で線路を撤去してはならない。</li></ol><h3 id="第49条-駅" tabindex="-1">第49条 駅 <a class="header-anchor" href="#第49条-駅" aria-label="Permalink to &quot;第49条 駅&quot;">​</a></h3><ol><li>駅には時計を設置する。</li></ol><hr><h1 id="第十七編-レッドストーン安全法" tabindex="-1">第十七編 レッドストーン安全法 <a class="header-anchor" href="#第十七編-レッドストーン安全法" aria-label="Permalink to &quot;第十七編 レッドストーン安全法&quot;">​</a></h1><h2 id="第一章-爆発物" tabindex="-1">第一章 爆発物 <a class="header-anchor" href="#第一章-爆発物" aria-label="Permalink to &quot;第一章 爆発物&quot;">​</a></h2><h3 id="第50条-爆発装置" tabindex="-1">第50条 爆発装置 <a class="header-anchor" href="#第50条-爆発装置" aria-label="Permalink to &quot;第50条 爆発装置&quot;">​</a></h3><ol><li>爆発装置の設置には許可を必要とする。</li><li>自動装置には安全機構を備えなければならない。</li></ol>',154)])])}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
